const esc = (value) => String(value).replace(/[&<>\"]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[char]));

function render(page) {
  const canonical = `${siteUrl}/${page.slug}`;
  const schema = { "@context": "https://schema.org", "@type": "Article", headline: page.title, description: page.description, url: canonical, dateModified: updated, author: { "@type": "Organization", name: "Nautical Dream Editorial Desk" }, publisher: { "@type": "Organization", name: "Nautical Dream" } };
  const faqSchema = { "@context": "https://schema.org", "@type": "FAQPage", mainEntity: page.faq.map(([q, a]) => ({ "@type": "Question", name: q, acceptedAnswer: { "@type": "Answer", text: a } })) };
  const sections = page.sections.map(([heading, paragraphs]) => `<section class="article-section"><h2>${esc(heading)}</h2>${paragraphs.map((p) => `<p>${esc(p)}</p>`).join("")}</section>`).join("");
  const failures = page.failures.map((item) => `<li>${esc(item)}</li>`).join("");
  const checklist = page.checklist.map((item) => `<li>${esc(item)}</li>`).join("");
  const faq = page.faq.map(([q, a]) => `<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join("");
  const related = page.related.map(([href, label]) => `<li><a href="${href}">${esc(label)}</a></li>`).join("");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(page.title)} | Nautical Dream</title><meta name="description" content="${esc(page.description)}"><link rel="canonical" href="${canonical}"><meta property="og:type" content="article"><meta property="og:site_name" content="Nautical Dream"><meta property="og:title" content="${esc(page.title)}"><meta property="og:description" content="${esc(page.description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${siteUrl}/${page.image}"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="styles.css"><script type="application/ld+json">${JSON.stringify(schema)}</script><script type="application/ld+json">${JSON.stringify(faqSchema)}</script></head><body><header class="site-header"><div class="shell nav"><a class="brand" href="index.html">NAUTICAL <span>DREAM</span></a><nav class="links" aria-label="Primary navigation"><a href="destinations.html">Destinations</a><a href="gear.html">Gear</a><a href="weather.html">Weather</a><a href="journal.html">Journal</a><a href="about.html">About</a></nav></div></header><main><section class="article-hero" style="--hero:url('${page.image}')"><div class="shell"><div class="eyebrow">${esc(page.eyebrow)}</div><h1>${esc(page.title)}</h1><p>${esc(page.lead)}</p></div></section><section class="section"><article class="shell article"><div class="article-meta"><span>By Nautical Dream Editorial Desk</span><span>Updated August 17, 2026</span><span>${esc(page.category)}</span></div><p class="lede">${esc(page.lead)}</p><div class="fact-grid">${page.quick.map((item, index) => `<div class="fact"><strong>${String(index + 1).padStart(2, "0")}</strong>${esc(item)}</div>`).join("")}</div>${sections}<section class="article-section"><h2>Failure modes to avoid</h2><ul class="authority-detail-list warning-list">${failures}</ul></section><section class="article-section"><h2>Field checklist</h2><ul class="authority-checklist">${checklist}</ul></section><section class="faq-section"><h2>Frequently asked questions</h2>${faq}</section><aside class="source-box"><h2>Verify current information</h2><p>Equipment procedures, waterway rules and operating conditions can change. Use current manufacturer documentation, local notices and primary boating-safety sources for the exact boat and trip.</p><ul><li><a href="https://www.uscgboating.org/" target="_blank" rel="noopener">U.S. Coast Guard Boating Safety</a></li><li><a href="https://nauticalcharts.noaa.gov/" target="_blank" rel="noopener">NOAA Nautical Charts</a></li><li><a href="https://www.weather.gov/marine/" target="_blank" rel="noopener">National Weather Service Marine Forecasts</a></li></ul></aside><aside class="related-content"><h2>Continue through the library</h2><div class="related-grid"><section><h3>Related guides</h3><ul>${related}</ul></section><section><h3>Library</h3><ul><li><a href="boating-library.html">Open the complete boating library</a></li><li><a href="boating-safety.html">Boating safety hub</a></li><li><a href="boat-maintenance.html">Boat maintenance hub</a></li></ul></section></div></aside><a class="back-link" href="boating-library.html">← Back to the boating library</a></article></section></main><footer class="footer"><div class="shell footer-row"><div><div class="brand">NAUTICAL <span>DREAM</span></div><p>Practical planning and trusted recommendations for life on the water.</p></div><div class="legal">© 2026 Nautical Dream · <a href="privacy.html">Privacy</a></div></div></footer></body></html>`;
}

function upsert(path, marker, block) {
  const full = join(root, path);
  let html = readFileSync(full, "utf8");
  const start = `<!-- ${marker} START -->`;
  const end = `<!-- ${marker} END -->`;
  const wrapped = `${start}${block}${end}`;
  const escapedStart = start.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const escapedEnd = end.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const pattern = new RegExp(`${escapedStart}[\\s\\S]*?${escapedEnd}`);
  if (pattern.test(html)) html = html.replace(pattern, wrapped);
  else html = html.replace("</main>", `${wrapped}</main>`);
  writeFileSync(full, html);
}

for (const page of pages) writeFileSync(join(root, page.slug), render(page));

const libraryCards = pages.map((page) => `<article class="hub-card library-card" data-library-card data-kind="${page.category.toLowerCase().includes("maintenance") ? "maintenance" : page.category.toLowerCase().includes("family") ? "family" : page.category.toLowerCase().includes("electrical") ? "gear" : "seamanship"}" data-search="${esc(`${page.title} ${page.description} ${page.lead}`.toLowerCase())}"><span>${esc(page.category)}</span><h3><a href="${page.slug}">${esc(page.title)}</a></h3><p>${esc(page.description)}</p><div class="library-card-footer"><small>Complete field guide</small><a class="text-link" href="${page.slug}">Read →</a></div></article>`).join("");
const libraryBlock = `<section class="section"><div class="shell"><div class="section-head"><div><div class="eyebrow" style="color:var(--blue)">New operating guides</div><h2>Ten more systems for real days on the water.</h2></div><p>Detailed procedures for locks, raft-ups, pets, propulsion, shore power, sanitation, bilge protection, current and emergency communications.</p></div><div class="hub-grid authority-index">${libraryCards}</div></div></section>`;
upsert("boating-library.html", "NAUTICAL EXPANSION TWO", libraryBlock);

